function taskDueLabel(t){
  if(t.done) return "Completed";
  if(!t.date) return t.due || "No date";
  const today=new Date(); today.setHours(0,0,0,0);
  const dueDate=new Date(`${t.date}T00:00:00`);
  if(Number.isNaN(dueDate.getTime())) return t.due || "No date";
  const diff=Math.round((dueDate-today)/86400000);
  if(diff<0) return `${Math.abs(diff)} day${diff===-1?"":"s"} overdue`;
  if(diff===0) return "Today";
  if(diff===1) return "Tomorrow";
  return dueDate.toLocaleDateString("en-IN",{day:"numeric",month:"short"});
}
