document.addEventListener("change",e=>{const habit=e.target.closest("[data-habit]");if(!habit)return;const habits=Learnix.Store.read(HABIT_KEY,{});habits[habit.dataset.habit]=habit.checked;Learnix.Store.write(HABIT_KEY,habits);const score=Learnix.ConsistencyScore.calculate(habits);const value=$("#consistencyValue"),bar=$("#consistencyBar"),message=$("#consistencyMessage"),feedback=$("#habitFeedback");if(value)value.textContent=score.score;const donut=$("#consistencyDonut");if(donut)donut.style.setProperty("--donut",score.score);if(bar)bar.style.width=`${score.score}%`;if(message)message.textContent=`${score.message} This is a simple habit check-in, not a grade.`;if(feedback)feedback.textContent=score.message;const habitLabel=habit.closest("label");const habitState=habitLabel?.querySelector("b");if(habitState)habitState.textContent=habit.checked?"Done":"+25";});
