async function syncStudentWorkspace(){
  if(!window.LearnixBackend?.enabled) return;
  try {
    const [cloudAssignments, cloudCourses, profile] = await Promise.all([
      window.LearnixBackend.listMyAssignments(), window.LearnixBackend.listMyCourses(), window.LearnixBackend.getMyProfile()
    ]);
    if(profile){
      state.profile={...state.profile,name:profile.full_name||state.profile.name,email:profile.email||state.profile.email,semester:profile.semester||state.profile.semester,studentId:profile.student_id||state.profile.studentId,program:profile.program||state.profile.program};
      state.academics={...state.academics,targetCgpa:Number(profile.target_cgpa??state.academics.targetCgpa)}; saveState(); updateIdentity();
    }
    const host=document.getElementById("cloud-assignment-list");
    if(host){
      host.innerHTML=cloudAssignments.length?cloudAssignments.map(a=>{const due=new Date(a.due_at);return `<article class="task-row"><div class="task-copy"><b>${escapeHtml(a.title)}</b><small>${escapeHtml(a.courses?.title||"Course")}${a.description?` · ${escapeHtml(a.description)}`:""}</small></div><span class="term-pill">Due ${escapeHtml(due.toLocaleDateString("en-IN",{day:"numeric",month:"short"}))}</span></article>`}).join(""):'<div class="empty-state">No teacher assignments yet. New assignments will appear here when your teacher publishes them.</div>';
      const status=document.getElementById("cloud-assignment-status"); if(status)status.textContent="Live assignments from your connected Learnix workspace.";
      const count=document.getElementById("cloud-assignment-count"); if(count)count.textContent=`${cloudAssignments.length} total`;
    }
    // Store connected courses for the courses view without replacing the polished demo cards when none are enrolled.
    window.learnixCloudCourses=cloudCourses; if(currentPage==="courses") renderPage("courses");
  } catch(error){const status=document.getElementById("cloud-assignment-status");if(status)status.textContent=`Could not load live assignments: ${error.message}`;}
}

function getReflections(){return Learnix.Store.read(REFLECTION_KEY,[]).filter(Boolean)}
function renderMomentumHistory(){
  const host=$("#reflectionHistory");
  if(!host)return;
  const items=getReflections();
  if(items.length){
    const scoreEl=$("#momentumScore");if(scoreEl)scoreEl.textContent=Number(items[0].score)||0;const gauge=$("#momentumGauge");if(gauge)gauge.style.setProperty("--gauge",Number(items[0].score)||0);
    const tipEl=$("#momentumTip");if(tipEl)tipEl.textContent=`✦ ${items[0].tip||"Take one manageable next step."}`;
  }
  if(!items.length){host.className="empty-state";host.innerHTML="No check-ins saved yet. Complete your first check-in above.";return}
  host.className="reflection-history";
  host.innerHTML=items.slice(0,7).map(item=>`<article class="simple-card" style="margin:10px 0;padding:15px"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center"><strong>${escapeHtml(item.dateLabel||"Check-in")}</strong><span class="term-pill">${Number(item.score)||0}/100</span></div><p style="margin:8px 0;color:#858ea7;font-size:12px">Energy ${item.energy}/5 · Focus ${item.focus}/10 · Confidence ${item.confidence}/10</p>${item.note?`<p style="margin:0;font-size:13px">${escapeHtml(item.note)}</p>`:""}<p style="margin:8px 0 0;font-size:12px;color:#6569e8">${escapeHtml(item.tip||"Take one manageable next step.")}</p></article>`).join("");
}
function submitMomentum(form){
  const energy=Number($("#energyLevel")?.value||3), focus=Number($("#focusLevel")?.value||5), confidence=Number($("#confidenceLevel")?.value||5);
  const score=Math.round((energy/5)*20+(focus/10)*40+(confidence/10)*40);
  const tip=energy<=2?"Choose a lighter task and take a short reset before studying.":focus<=4?"Put distractions away and try one 15-minute focused sprint.":confidence<=4?"Review one example, then solve a similar question with your notes.":"Use your momentum on the nearest important assignment.";
  const note=$("#momentumNote")?.value.trim()||"";
  const now=new Date();
  const entry={id:Date.now(),date:now.toISOString(),dateLabel:now.toLocaleString("en-IN",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"}),energy,focus,confidence,score,note,tip};
  const items=getReflections();items.unshift(entry);Learnix.Store.write(REFLECTION_KEY,items.slice(0,30));
  const scoreEl=$("#momentumScore");if(scoreEl)scoreEl.textContent=score;const gauge=$("#momentumGauge");if(gauge)gauge.style.setProperty("--gauge",score);
  const tipEl=$("#momentumTip");if(tipEl)tipEl.textContent=`✦ ${tip}`;
  renderMomentumHistory();toast("Momentum check-in saved.");
}

document.addEventListener("submit",e=>{if(e.target?.id==="momentumForm"){e.preventDefault();submitMomentum(e.target)}});
document.addEventListener("submit",e=>{if(e.target?.id!=="academicGoalsForm")return;e.preventDefault();const cgpa=Number($("#goalCgpa").value),target=Number($("#goalTarget").value),progress=Number($("#goalProgress").value);if(![cgpa,target,progress].every(Number.isFinite)||cgpa<0||cgpa>10||target<0||target>10||progress<0||progress>100){toast("Enter valid values: CGPA 0–10 and progress 0–100%.");return}state.academics={...state.academics,cgpa,targetCgpa:target,courseProgress:progress};saveState();renderPage("settings");toast("Academic goals saved.")});
